private void ack(Cur cur, ByteArrayOutputStream out, int level, boolean withEcn) {
    long largest = cur.varint();
    long delay = cur.varint();
    long count = cur.varint();
    long first = cur.varint();
    out.writeBytes(vi(largest));
    out.writeBytes(vi(delay));
    out.writeBytes(vi(count));
    out.writeBytes(vi(first));
    if (first > largest) throw new Fail(ENCODING, 0);
    ArrayList<long[]> ranges = new ArrayList<>();
    long low = largest - first;
    ranges.add(new long[] {low, largest + 1});
    for (long i = 1; i < count; i++) {
        long gap = cur.varint();
        long range = cur.varint();
        out.writeBytes(vi(gap));
        out.writeBytes(vi(range));
        if (low < gap + 2) throw new Fail(ENCODING, 0);
        long high = low - gap - 2;
        if (range > high) throw new Fail(ENCODING, 0);
        low = high - range;
        ranges.add(new long[] {low, high + 1});
    }
    long[] counters = null;
    if (withEcn) {
        counters = new long[] {cur.varint(), cur.varint(), cur.varint()};
        for (long counter : counters) out.writeBytes(vi(counter));
    }
    for (long[] range : ranges) acks[level].add(range[0], range[1], journal);
    if (counters != null) {
        for (int i = 0; i < 3; i++) {
            if (counters[i] > ecn[level][i]) {
                final long previous = ecn[level][i];
                final int column = i;
                ecn[level][i] = counters[i];
                journal.add(() -> ecn[level][column] = previous);
            }
        }
    }
}

