private void stream(int code, Cur cur, ByteArrayOutputStream out) {
    long id = cur.varint();
    out.writeBytes(vi(id));
    boolean hasOffset = (code & 4) != 0;
    boolean hasLength = (code & 2) != 0;
    boolean fin = (code & 1) != 0;
    long offset;
    if (hasOffset) {
        offset = cur.varint();
        out.writeBytes(vi(offset));
    } else {
        offset = 0;
    }
    byte[] data;
    if (hasLength) {
        long length = cur.varint();
        data = cur.take(length);
        out.writeBytes(vi(data.length));
    } else {
        data = cur.rest();
    }
    out.writeBytes(data);

    Stream stream = reference(id, true);
    if (offset > MAX62 - data.length) throw new Fail(ENCODING, 0);
    long end = offset + data.length;
    Long known = stream.finalSize;
    if (known != null) {
        if (end > known) throw new Fail(FINAL_SIZE, 0);
        if (fin && end != known) throw new Fail(FINAL_SIZE, 0);
    } else if (fin && end < stream.high) {
        throw new Fail(FINAL_SIZE, 0);
    }
    long candidate = Math.max(stream.high, end);
    credit(candidate, stream.high);
    if (stream.reset == null && !stream.bytes.put(offset, data, journal)) throw new Fail(VIOLATION, 0);
    setHigh(stream, candidate);
    if (fin && known == null) setFinal(stream, end);
}

